const formValue = (data: FormData, key: string) => String(data.get(key) || '').trim();
const lines = (value: string) => value.split('\n').map(v => v.trim()).filter(Boolean);
const messageOf = (error: any) => error?.message || 'We could not save your changes. Please try again.';
const defaultCategories = ['Website templates', 'Source code', 'Scripts', 'UI kits', 'Design assets', 'Documentation'];
function Field({ label, note, wide, children }: { label: string; note?: string; wide?: boolean; children: React.ReactNode }) { const id = React.useId(); return <label className={`market-field${wide ? ' market-field-wide' : ''}`}><span id={`${id}-label`}>{label}</span>{React.isValidElement(children) ? React.cloneElement(children as React.ReactElement<any>, { 'aria-labelledby': `${id}-label`, 'aria-describedby': note ? `${id}-hint` : undefined }) : children}{note && <small id={`${id}-hint`}>{note}</small>}</label>; }
function CreatorWelcome() {
  const { navigate } = useApp();
  return <div className="market-auth-invite"><div><p className="eyebrow">Made by you. Shared with the world.</p><h1>Make something.<br/>Make it yours.</h1><p>A home for your original digital products, your creative business, and the people who love what you make.</p><div className="market-auth-actions"><button className="btn btn-primary" onClick={() => navigate('/register', undefined, authReturnSearch('creator'))}>Start your creator journey<ArrowRight size={16}/></button><button className="btn btn-secondary" onClick={() => navigate('/login', undefined, authReturnSearch('creator'))}>Sign in</button></div></div><div className="market-benefits">{[[Store, 'Your own little corner', 'Create a storefront that tells your story and puts your work first.'], [Package, 'Good work. Clear delivery.', 'Upload your digital products privately and give buyers access after verified payment.'], [Users, 'Build something lasting', 'Offer memberships, grow your collection, and keep track of it in one place.']].map(([Icon, title, description]: any) => <div key={title} className="market-benefit"><span><Icon size={21}/></span><div><h3>{title}</h3><p>{description}</p></div></div>)}</div></div>;
}
function ProfileForm({ creator, config, onboard, onSaved }: { creator?: CreatorCard; config: MarketplaceConfig | null; onboard?: boolean; onSaved: () => Promise<void> }) {
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [success, setSuccess] = useState(false);
  const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setMessage(''); setSuccess(false); const profile: any = { displayName: formValue(data, 'displayName'), slug: formValue(data, 'slug').toLowerCase(), headline: formValue(data, 'headline'), bio: formValue(data, 'bio') }; const avatarUrl = formValue(data, 'avatarUrl'); if (avatarUrl) profile.avatarUrl = avatarUrl; if (data.get('publishBusiness') === 'on') profile.publicBusiness = { businessName: formValue(data, 'businessName'), businessAddress: formValue(data, 'businessAddress'), supportEmail: formValue(data, 'supportEmail'), supportPhone: formValue(data, 'supportPhone'), grievanceName: formValue(data, 'grievanceName'), publishConsent: true }; if (onboard) Object.assign(profile, { legalName: formValue(data, 'legalName'), pan: formValue(data, 'pan').toUpperCase(), kycConsent: data.get('kycConsent') === 'on', phone: formValue(data, 'phone').replace(/\s/g, ''), adult: data.get('adult') === 'on', ownsRights: data.get('ownsRights') === 'on', acceptAgreement: data.get('acceptAgreement') === 'on', agreementVersion: config?.agreement && typeof config.agreement === 'object' ? config.agreement.version : '' }); try { await (onboard ? MarketplaceService.onboard(profile) : MarketplaceService.updateProfile(profile)); setSuccess(true); setMessage(onboard ? 'Your creator profile has been submitted for review. You can start preparing your products.' : 'Profile saved. Material changes may need a fresh review.'); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(false); } };
  const publicBusiness = creator?.publicBusiness;
  const agreement = config?.agreement && typeof config.agreement === 'object' ? config.agreement : null; const agreementTerms = agreement?.terms || [];
  return <div className={onboard ? 'market-onboard' : ''}><section className="market-panel"><h2>{onboard ? 'A little about you.' : 'Your storefront, your story.'}</h2><p>{onboard ? 'Choose a name and introduce your work. Your legal and payout details stay private.' : 'Help people get to know the person behind the products. Keep private contact and payment details out of your bio.'}</p><form onSubmit={submit} className="market-form" key={creator?.id || 'new-creator'}><div className="market-form-grid"><Field label="Creator or studio name"><input name="displayName" defaultValue={creator?.displayName || ''} required minLength={2} maxLength={80} autoComplete="organization" placeholder="Your creative name"/></Field><Field label="Storefront name" note={onboard ? '3–50 lowercase letters, numbers, or hyphens.' : 'Your storefront address is permanent. Contact support to request a change.'}><input name="slug" defaultValue={creator?.slug || ''} readOnly={!onboard} required pattern={'[a-z0-9][a-z0-9\\-]{2,49}'} maxLength={50} placeholder="your-studio" autoCapitalize="none" spellCheck={false}/></Field><Field label="A short introduction" wide note="One clear line about what you make."><input name="headline" defaultValue={creator?.headline || ''} maxLength={160} placeholder="Useful resources for beautifully simple websites."/></Field><Field label="Your story" wide><textarea name="bio" defaultValue={creator?.bio || ''} maxLength={3000} rows={5} placeholder="Tell people a little about your work and what inspires it."/></Field>{!onboard && <Field label="Profile image URL" wide note="Use a public HTTPS image. Never use an identity document or a paid download link."><input name="avatarUrl" type="url" defaultValue={creator?.avatarUrl || ''} placeholder="https://…"/></Field>}{onboard && <><Field label="Your legal name" note="Private. Used for identity and payout checks."><input name="legalName" required minLength={2} maxLength={120} autoComplete="name"/></Field><Field label="PAN number" note="Private seller KYC only. Buyers do not need PAN. This is encrypted and never displayed on your storefront."><input name="pan" required pattern="[A-Za-z]{5}[0-9]{4}[A-Za-z]" maxLength={10} autoComplete="off" autoCapitalize="characters" spellCheck={false}/></Field><Field label="Mobile number" note="An Indian number for private account and payout support."><input name="phone" type="tel" required pattern="(\+?91)?[6-9][0-9]{9}" autoComplete="tel" placeholder="Your 10-digit mobile number"/></Field></>}</div><fieldset className="market-public-business"><legend>Seller information shown to buyers</legend><p className="market-note">These business and support details will be visible on your storefront. They are separate from your private identity documents and bank details. Complete them before your storefront can be approved.</p><div className="market-form-grid"><Field label="Legal or trading business name"><input name="businessName" defaultValue={publicBusiness?.businessName || ''} required minLength={2} maxLength={120} autoComplete="organization"/></Field><Field label="Public support email"><input name="supportEmail" type="email" defaultValue={publicBusiness?.supportEmail || ''} required maxLength={254} autoComplete="email"/></Field><Field label="Public business address" wide note="Use the valid business address you are authorised to publish."><textarea name="businessAddress" defaultValue={publicBusiness?.businessAddress || ''} required minLength={10} maxLength={600} rows={3} autoComplete="street-address"/></Field><Field label="Public support phone"><input name="supportPhone" type="tel" defaultValue={publicBusiness?.supportPhone || ''} required pattern="(\+?91)?[6-9][0-9]{9}" maxLength={13} autoComplete="tel"/></Field><Field label="Grievance contact name"><input name="grievanceName" defaultValue={publicBusiness?.grievanceName || ''} required minLength={2} maxLength={120} autoComplete="name"/></Field></div><label className="market-check"><input type="checkbox" name="publishBusiness" required/><span>I authorise publication of the business address, support contacts and grievance name above so buyers can identify and contact this seller. I confirm these details are accurate.</span></label></fieldset>{onboard && <><label className="market-check"><input name="kycConsent" type="checkbox" required/><span>I consent to private processing of my seller PAN and identity details for KYC, provider onboarding and legal obligations. PAN is never displayed on my storefront. <a href="/policies/privacy">Privacy policy</a></span></label><label className="market-check"><input type="checkbox" name="adult" required/><span>I am at least 18 and can legally enter into this agreement.</span></label><label className="market-check"><input type="checkbox" name="ownsRights" required/><span>I own my products, or hold the licences needed to sell and distribute every included file.</span></label><label className="market-check"><input type="checkbox" name="acceptAgreement" required/><span>I have read and accept the <a href="/policies/creator-agreement">Creator Agreement</a> shown here, the <a href="/policies/terms">marketplace Terms</a>, and the <a href="/policies/refund">Refund policy</a>.</span></label></>}{message && <Notice tone={success ? 'success' : 'error'}>{message}</Notice>}<div className="market-form-actions"><AsyncButton type="submit" busy={busy} disabled={!!onboard && (!agreement || !agreement.version)} busyLabel={onboard ? 'Creating your space…' : 'Saving your profile…'}>{onboard ? 'Create your storefront' : 'Save profile'}<ArrowRight size={16}/></AsyncButton></div></form></section>{onboard && <aside className="market-agreement"><p className="eyebrow">Before you begin</p><h2>{agreement ? agreement.title : 'A good place to create.'}</h2>{typeof config?.settings?.commissionBps === 'number' && <p className="market-note">Marketplace commission: <strong>₹20 per item sold</strong>. Plan fees, payment charges and applicable taxes are separate.</p>}<ul>{(agreementTerms.length ? agreementTerms : ['Sell only original or properly licensed digital products.', 'Your profile and every product are reviewed before publication.', 'Complete identity and payment-provider verification before selling.', 'Help buyers with missing files, genuine defects, and delivery issues.']).map((term, index) => <li key={index}><Check size={15}/><span>{term}</span></li>)}</ul>{agreement && <p className="market-note">Agreement version {agreement.version}</p>}<p className="market-note"><a href="/policies/creator-agreement">Full creator agreement</a> · <a href="/policies/terms">Terms</a> · <a href="/policies/privacy">Privacy</a> · <a href="/policies/refund">Refund policy</a></p></aside>}</div>;
}

function CreatorAgreementUpdate({ creator, config, onSaved }: { creator: CreatorCard; config: MarketplaceConfig | null; onSaved: () => Promise<void> }) {
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const agreement = config?.agreement;
  if (!agreement || typeof agreement !== 'object' || (creator.agreementVersion === agreement.version && creator.agreementAcceptedAt)) return null;
  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (new FormData(event.currentTarget).get('acceptAgreement') !== 'on') return;
    setBusy(true); setMessage('');
    try { await MarketplaceService.acceptAgreement(agreement.version); await onSaved(); }
    catch (error) { setMessage(messageOf(error)); }
    finally { setBusy(false); }
  };
  return <section className="market-panel market-agreement-update"><h2>A quick review before your next chapter.</h2><p>Read and accept the current Creator Agreement before submitting new offers or taking new creator payments. Your valid existing customer purchases stay available.</p><details><summary>Read the current creator terms</summary><ul>{agreement.terms.map((term, index) => <li key={index}>{term}</li>)}</ul><p className="market-note">Version {agreement.version} · <a href="/policies/creator-agreement">Full Creator Agreement</a></p></details><form className="market-form" onSubmit={submit}><label className="market-check"><input type="checkbox" name="acceptAgreement" required/><span>I have read and accept this version of the <a href="/policies/creator-agreement">Creator Agreement</a>, the <a href="/policies/terms">Terms</a> and the <a href="/policies/refund">Refund policy</a>.</span></label>{message && <Notice tone="error">{message}</Notice>}<AsyncButton type="submit" busy={busy} busyLabel="Recording your acceptance…">Accept current creator terms<Check size={15}/></AsyncButton></form></section>;
}

function PayoutForm({ creator, onSaved }: { creator: CreatorCard; onSaved: () => Promise<void> }) {
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [success, setSuccess] = useState(false);
  const kyc = creator.kyc as { status?: string; panLast4?: string; bankLast4?: string } | undefined;
  const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); setBusy(true); setMessage(''); setSuccess(false); try { const result = await MarketplaceService.submitKyc({ legalName: formValue(data, 'legalName'), pan: formValue(data, 'pan').toUpperCase(), accountHolder: formValue(data, 'accountHolder'), bankAccount: formValue(data, 'bankAccount'), ...(formValue(data, 'upiId') ? { upiId: formValue(data, 'upiId') } : {}), ifsc: formValue(data, 'ifsc').toUpperCase(), address: { line1: formValue(data, 'line1'), city: formValue(data, 'city'), state: formValue(data, 'state'), postalCode: formValue(data, 'postalCode'), country: 'IN' }, consent: data.get('consent') === 'on' }); setSuccess(true); setMessage(result.message || 'Details saved. Your payment provider must verify and activate your payout account separately.'); form.reset(); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(false); } };
  return <div className="market-overview-grid"><section className="market-panel"><h2>Let’s get your payouts ready.</h2><p>Use details that match your identity and bank account. These fields are private and never appear on your storefront.</p><div className="market-status-line"><span>Details submission</span><StatusPill value={kyc?.status || 'not_submitted'}/>{kyc?.panLast4 && <span className="market-note">PAN ending {kyc.panLast4} · account ending {kyc.bankLast4 || '—'}</span>}</div><form onSubmit={submit} className="market-form"><div className="market-form-grid"><Field label="Legal name"><input name="legalName" required minLength={2} maxLength={120} autoComplete="name"/></Field><Field label="PAN"><input name="pan" required pattern="[A-Za-z]{5}[0-9]{4}[A-Za-z]" maxLength={10} autoCapitalize="characters" autoComplete="off"/></Field><Field label="Bank account holder"><input name="accountHolder" required minLength={2} maxLength={120} autoComplete="off"/></Field><Field label="Bank account number"><input name="bankAccount" required pattern="[0-9]{9,18}" inputMode="numeric" autoComplete="off"/></Field><Field label="UPI ID (optional)" note="Stored privately for provider onboarding. UPI payout availability and reserve support depend on the approved payment product."><input name="upiId" maxLength={320} autoComplete="off" placeholder="yourname@bank"/></Field><Field label="IFSC"><input name="ifsc" required pattern="[A-Za-z]{4}0[A-Za-z0-9]{6}" maxLength={11} autoCapitalize="characters" autoComplete="off"/></Field><Field label="Address" wide><input name="line1" required minLength={5} maxLength={300} autoComplete="street-address"/></Field><Field label="City"><input name="city" required minLength={2} autoComplete="address-level2"/></Field><Field label="State"><input name="state" required minLength={2} autoComplete="address-level1"/></Field><Field label="PIN code"><input name="postalCode" required pattern="[1-9][0-9]{5}" maxLength={6} inputMode="numeric" autoComplete="postal-code"/></Field></div><label className="market-check"><input name="consent" type="checkbox" required/><span>I confirm these details are accurate and authorise their use for identity, bank, tax and payment-provider verification as described in the Privacy Policy.</span></label>{message && <Notice tone={success ? 'success' : 'error'}>{message}</Notice>}<AsyncButton type="submit" busy={busy} busyLabel="Saving your private details…">Submit payout details<ShieldCheck size={16}/></AsyncButton></form></section><aside className="market-panel"><ShieldCheck size={28} strokeWidth={1.3}/><h2 style={{ marginTop: 18 }}>A few separate steps.</h2><p>Saving these details is the first step. It is different from profile approval, payment-provider KYC, or confirmation that money has reached your bank.</p><div className="market-provider-list">{['cashfree', 'razorpay', 'easebuzz'].map(provider => { const account = creator.providerAccounts?.[provider]; return <div className="market-provider-row" key={provider}><span style={{ textTransform: 'capitalize' }}>{provider}</span><StatusPill value={account?.status || 'not_connected'}/></div>; })}</div><p className="market-note">If the payment provider requires additional documents, complete its approved verification process. We will never ask for a UPI PIN, bank password or OTP here.</p></aside></div>;
}

const initialListing = { title: '', shortDescription: '', description: '', category: defaultCategories[0], price: '', image: '', features: '', whatsIncluded: '', tags: '', licenseTerms: '', requirements: '', version: '1.0', previewUrl: '', membershipEligible: false };
function ListingEditor({ listing, categories, allowMembership, onClose, onSaved }: { listing: CreatorListing | null; categories: string[]; allowMembership: boolean; onClose: () => void; onSaved: () => Promise<void> }) {
  const [draft, setDraft] = useState<CreatorListing | null>(listing); const [busy, setBusy] = useState(''); const [message, setMessage] = useState(''); const [success, setSuccess] = useState(false); const [file, setFile] = useState<File | null>(null); const [dirty, setDirty] = useState(false); const [fileUrl, setFileUrl] = useState('');
  const values = draft ? { ...initialListing, ...draft, features: draft.features.join('\n'), whatsIncluded: draft.whatsIncluded.join('\n'), tags: draft.tags.join(','), requirements: Array.isArray(draft.requirements) ? draft.requirements.join('\n') : draft.requirements || '' } : initialListing;
  const save = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy('save'); setMessage(''); setSuccess(false); const payload: any = { title: formValue(data, 'title'), shortDescription: formValue(data, 'shortDescription'), description: formValue(data, 'description'), category: formValue(data, 'category'), price: Number(formValue(data, 'price')), image: formValue(data, 'image'), features: lines(formValue(data, 'features')), whatsIncluded: lines(formValue(data, 'whatsIncluded')), tags: formValue(data, 'tags').split(',').map(t => t.trim()).filter(Boolean), licenseTerms: formValue(data, 'licenseTerms'), requirements: formValue(data, 'requirements'), version: formValue(data, 'version') || '1.0', membershipEligible: data.get('membershipEligible') === 'on', ownsRights: data.get('ownsRights') === 'on' }; if (formValue(data, 'previewUrl')) payload.previewUrl = formValue(data, 'previewUrl'); try { const result = await (draft ? MarketplaceService.updateListing(draft.id, payload) : MarketplaceService.createListing(payload)); setDraft(result.listing); setDirty(false); setSuccess(true); setMessage('Draft saved. Add your private ZIP below, then submit it for review.'); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(''); } };
  const upload = async () => { if (!draft || !file) return; if (!file.name.toLowerCase().endsWith('.zip') || file.size > 10 * 1024 * 1024) { setSuccess(false); setMessage('Choose a ZIP file up to 10 MB. It uploads directly to private Storage.'); return; } setBusy('upload'); setMessage(''); setSuccess(false); try { const result = await MarketplaceService.uploadListing(draft.id, file); setDraft(result.listing); setSuccess(true); setMessage(result.message || 'Your ZIP has been uploaded privately.'); setFile(null); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(''); } };
  const importFile = async () => { if (!draft || !fileUrl.trim()) return; setBusy('import'); setMessage(''); setSuccess(false); try { const result = await MarketplaceService.importListing(draft.id, fileUrl.trim()); setDraft(result.listing); setSuccess(true); setMessage(result.message || 'The ZIP was copied into private Storage.'); setFileUrl(''); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(''); } };
  const submit = async () => { if (!draft) return; setBusy('submit'); setMessage(''); setSuccess(false); try { const result = await MarketplaceService.submitListing(draft.id); setDraft(result.listing); setSuccess(true); setMessage('Your product has been submitted for review. It will appear on your storefront after approval.'); await onSaved(); } catch (error) { setMessage(messageOf(error)); } finally { setBusy(''); } };
  const fileReady = !!(draft?.file as any)?.uploaded; const publishedFile = !!(draft?.file as any)?.published;
  return <Modal isOpen onClose={() => { if (!busy) onClose(); }} title={draft ? 'Your product' : 'Make room for a new product'} maxWidth="3xl" mobileFullscreen><div className="market-modal-form"><p className="market-note">Your changes are saved as a draft and reviewed before publication. Paid files stay private.</p>{draft && <div className="market-status-line"><StatusPill value={draft.status}/><span className="market-note">{fileReady ? 'Private ZIP uploaded' : 'ZIP not uploaded yet'}</span></div>}<form className="market-form" onSubmit={save} onChange={() => setDirty(true)}><div className="market-form-grid"><Field label="Product name" wide><input name="title" defaultValue={values.title} required minLength={3} maxLength={140}/></Field><Field label="Category"><select name="category" defaultValue={values.category}>{categories.map(category => <option key={category}>{category}</option>)}</select></Field><Field label="Price (INR)" note="Minimum ₹21 to cover the ₹20 fee per item sold. Provider charges and applicable taxes may also apply."><input name="price" type="number" min={21} max={100000} step="0.01" defaultValue={values.price} required/></Field><Field label="Short description" wide note="20–400 characters. Explain the benefit in a sentence or two."><textarea name="shortDescription" defaultValue={values.shortDescription} required minLength={20} maxLength={400} rows={2}/></Field><Field label="Full description" wide note="At least 50 characters. Describe who this is for and what buyers can expect."><textarea name="description" defaultValue={values.description} required minLength={50} maxLength={15000} rows={5}/></Field><Field label="Cover image URL" wide note="Public HTTPS image only. Do not enter a paid download URL here."><input name="image" type="url" defaultValue={values.image} required placeholder="https://…"/></Field><Field label="Key features" note="One feature per line, up to 20."><textarea name="features" defaultValue={values.features} required maxLength={4000} rows={4}/></Field><Field label="What is included" note="One file or inclusion per line, up to 30."><textarea name="whatsIncluded" defaultValue={values.whatsIncluded} required maxLength={6000} rows={4}/></Field><Field label="Licence terms" wide note="Explain permitted use, redistribution limits, and any third-party licences."><textarea name="licenseTerms" defaultValue={values.licenseTerms} required minLength={10} maxLength={4000} rows={3}/></Field><Field label="Requirements" wide><textarea name="requirements" defaultValue={values.requirements} maxLength={2000} rows={2}/></Field><Field label="Version"><input name="version" defaultValue={values.version} maxLength={40} required/></Field><Field label="Tags" note="Comma separated, up to 12."><input name="tags" defaultValue={values.tags} maxLength={480}/></Field><Field label="Live preview URL" wide note="Optional public preview. Never link the paid ZIP here."><input name="previewUrl" type="url" defaultValue={values.previewUrl} placeholder="https://…"/></Field></div><label className="market-check"><input name="membershipEligible" type="checkbox" defaultChecked={values.membershipEligible} disabled={!allowMembership && !values.membershipEligible}/><span>Include this product in customer memberships (Studio ₹899 feature). Verified members receive access during their paid period.</span></label><label className="market-check"><input name="ownsRights" type="checkbox" required/><span>I own or have the right to sell every included file. The description and licence accurately describe this product.</span></label><AsyncButton type="submit" busy={busy === 'save'} disabled={!!busy} busyLabel="Saving your draft…">Save draft<Check size={16}/></AsyncButton></form><hr className="market-section-divider"/><h3 style={{ fontSize: 17 }}>Add the good stuff.</h3><div className="market-upload-box"><p>{draft ? fileReady ? `Your private ZIP is uploaded${(draft.file as any)?.fileName ? `: ${(draft.file as any).fileName}` : '.'}` : 'Upload the ZIP buyers receive after a verified payment.' : 'Save your draft first, then upload the product ZIP here.'}</p><input type="file" accept=".zip,application/zip,application/x-zip-compressed" disabled={!draft || publishedFile || !!busy} aria-label="Private product ZIP" onChange={event => { setFile(event.target.files?.[0] || null); }}/><p>{publishedFile ? 'This published ZIP is kept for previous buyers. Create a new product listing to offer a different file or version.' : 'ZIP only · Maximum 10 MB · Direct to private Supabase Storage for review'}</p><AsyncButton className="btn-secondary" busy={busy === 'upload'} disabled={!draft || !file || publishedFile || !!busy} busyLabel="Uploading your private ZIP…" onClick={() => void upload()}><Upload size={15}/>Upload ZIP</AsyncButton><div className="market-upload-link"><h4>Or import a direct ZIP link</h4><p className="market-note">Public HTTPS ZIP only, up to 10 MB, without redirects or sign-in. The file is copied to private Storage. Buyers never receive this original URL. For a sharing-page link, download the ZIP and use Upload instead.</p><input type="url" value={fileUrl} onChange={event => setFileUrl(event.target.value)} disabled={!draft || publishedFile || !!busy} aria-label="Direct HTTPS ZIP URL" placeholder="https://files.example.com/product.zip"/><AsyncButton className="btn-secondary" busy={busy === 'import'} disabled={!draft || !fileUrl.trim() || publishedFile || !!busy} busyLabel="Copying the private ZIP…" onClick={() => void importFile()}>Import ZIP link</AsyncButton></div></div>{message && <div style={{ marginTop: 18 }}><Notice tone={success ? 'success' : 'error'}>{message}</Notice></div>}{dirty && <p className="market-note">Save your changes before submitting the product for review.</p>}<div className="market-form-actions" style={{ marginTop: 25 }}><AsyncButton busy={busy === 'submit'} busyLabel="Submitting for review…" disabled={!draft || !fileReady || draft.status === 'pending' || dirty || !!busy} onClick={() => void submit()}>Submit for review<ArrowRight size={15}/></AsyncButton><button className="btn btn-secondary" disabled={!!busy} onClick={onClose}>Done</button></div></div></Modal>;
}

function CreatorMembershipPlans({ creator }: { creator: CreatorCard }) {
  const [plans, setPlans] = useState<MarketPlan[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [editing, setEditing] = useState<MarketPlan | null | undefined>(undefined); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { const result = await SubscriptionService.ownMembershipPlans(); setPlans(result.plans || []); } catch (err) { setError(messageOf(err)); } finally { setLoading(false); } }, [creator.id]);
  useEffect(() => { void load(); }, [load]);
  const save = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setMessage(''); try { await MarketplaceService.saveMembershipPlan(editing?.id, { name: formValue(data, 'name'), description: formValue(data, 'description'), amount: Number(formValue(data, 'amount')), interval: formValue(data, 'interval'), billingMode: formValue(data, 'billingMode'), features: lines(formValue(data, 'features')), published: false }); setEditing(undefined); setMessage('Membership offer submitted for review. It appears on your approved storefront after publication.'); await load(); } catch (err) { setMessage(messageOf(err)); } finally { setBusy(false); } };
  return <section><div className="market-section-heading"><div><h2>More reasons to come back.</h2><p>Offer ongoing access to the products you mark as membership eligible.</p></div><button className="btn btn-primary" onClick={() => { setMessage(''); setEditing(null); }}><Plus size={15}/>New offer</button></div>{message && editing === undefined && <Notice>{message}</Notice>}{loading ? <MarketLoading label="Loading your membership offers…"/> : error ? <MarketError message={error} onRetry={load}/> : plans.length ? <div className="market-plan-grid">{plans.map(plan => <article className="market-plan-card" key={plan.id}><StatusPill value={plan.published ? 'published' : 'not_published'}/><h2>{plan.name}</h2><p className="market-plan-description">{plan.description}</p><div className="market-plan-price">{marketplaceMoney(plan.amount)}<small> / {plan.interval}</small></div><p className="market-note">{plan.billingMode === 'automatic' ? 'Automatic renewal, subject to an approved provider mandate.' : 'Manual renewal. Members pay for each period separately.'}</p><ul className="market-plan-features">{plan.features.map((feature, i) => <li key={i}><Check size={14}/>{feature}</li>)}</ul><button className="btn btn-secondary" onClick={() => { setMessage(''); setEditing(plan); }}><Pencil size={14}/>Edit offer</button></article>)}</div> : <MarketEmpty title="Turn a collection into a connection" description="Create a membership and choose which of your products members can access. Start with a clear benefit and honest renewal terms." action="Create a membership offer" onAction={() => setEditing(null)} icon={Users}/>}
  <div className="market-inline-notice">Automatic renewal requires provider approval and a verified customer mandate. Publishing an offer does not enable automatic charges by itself. Members receive access only for verified paid periods.</div>
  {editing !== undefined && <Modal isOpen onClose={() => { if (!busy) setEditing(undefined); }} title={editing ? 'Edit your membership offer' : 'Create a membership offer'} maxWidth="2xl"><form className="market-form" onSubmit={save}><div className="market-form-grid"><Field label="Membership name" wide><input name="name" defaultValue={editing?.name || ''} required minLength={2} maxLength={70}/></Field><Field label="What members receive" wide><textarea name="description" defaultValue={editing?.description || ''} required minLength={10} maxLength={400}/></Field><Field label="Price (INR)"><input type="number" name="amount" defaultValue={editing?.amount || ''} required min={1} max={100000} step="0.01"/></Field><Field label="Billing period"><select name="interval" defaultValue={editing?.interval || 'month'}><option value="month">Monthly</option><option value="year">Yearly</option></select></Field><Field label="Renewal"><select name="billingMode" defaultValue={editing?.billingMode || 'manual'}><option value="manual">Manual: customer pays for each period</option><option value="automatic">Automatic: approved mandate required</option></select></Field><Field label="Benefits" wide note="Up to 12 benefits, one per line, no more than 120 characters each."><textarea name="features" defaultValue={editing?.features.join('\n') || ''} required maxLength={3000}/></Field></div><label className="market-check"><input type="checkbox" required/><span>I will provide these benefits. I understand the offer and any changes need review before publication.</span></label>{message && <Notice tone="error">{message}</Notice>}<div className="market-form-actions"><AsyncButton type="submit" busy={busy} busyLabel="Submitting your offer…">Submit for review<Check size={15}/></AsyncButton><button type="button" className="btn btn-secondary" disabled={busy} onClick={() => setEditing(undefined)}>Cancel</button></div></form></Modal>}
  </section>;
}

function MembershipEarnings({ earnings }: { earnings: any }) {
  if (!earnings) return null;
  const entries = Array.isArray(earnings.entries) ? earnings.entries : [];
  return <section><hr className="market-section-divider"/><div className="market-section-heading"><div><h2>Your membership business.</h2><p>Verified membership charges, recorded commission and adjustments are shown separately from product sales.</p></div></div><div className="market-stats">{[['Membership charges', earnings.grossPaise], ['Recorded commission', earnings.commissionPaise], ['Recorded refunds', earnings.refundPaise], ['Membership payable balance', earnings.payablePaise]].map(([label, amount]) => <div className="market-stat" key={String(label)}><p>{String(label)}</p><strong>{marketplaceMoney(Number(amount || 0) / 100)}</strong></div>)}</div><p className="market-inline-notice">These are recorded proceeds, not a bank-credit confirmation. Refunds, disputes, provider fees, approved reserves and the provider’s settlement process can change the final payout.</p>{entries.length ? <div className="market-table-wrap"><table className="market-table"><thead><tr><th>Membership</th><th>Paid period</th><th>Charge</th><th>Recorded proceeds</th><th>Settlement</th></tr></thead><tbody>{entries.map((entry: any) => <tr key={entry.id}><td>{entry.planName || 'Membership'}<small>{String(entry.provider || '').replace(/^./, letter => letter.toUpperCase())}</small></td><td>{marketplaceDate(entry.periodStart)}<small>Through {marketplaceDate(entry.periodEnd)}</small></td><td>{marketplaceMoney(Number(entry.grossPaise || 0) / 100)}{entry.refundedPaise > 0 && <small>Refunded: {marketplaceMoney(entry.refundedPaise / 100)}</small>}</td><td>{marketplaceMoney(Number(entry.netSellerPaise || 0) / 100)}<small>{String(entry.status || 'payable').replace(/_/g, ' ')}</small></td><td><StatusPill value="pending_provider"/><small>Provider confirmation required</small></td></tr>)}</tbody></table></div> : <p className="market-note">Verified paid membership charges will appear here.</p>}</section>;
}

export const CreatorHubPage: React.FC = () => {
  const { isAuthenticated, navigate } = useApp(); const [workspace, setWorkspace] = useState<CreatorWorkspace | null>(null); const [config, setConfig] = useState<MarketplaceConfig | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [tab, setTab] = useState('overview'); const [editing, setEditing] = useState<CreatorListing | null | undefined>(undefined); const [actionBusy, setActionBusy] = useState(''); const [message, setMessage] = useState('');
  const load = useCallback(async (quiet = false) => { if (!isAuthenticated) { setLoading(false); return; } if (!quiet) setLoading(true); setError(''); const results = await Promise.allSettled([MarketplaceService.me(), MarketplaceService.config()]); if (results[0].status === 'fulfilled') setWorkspace(results[0].value); else setError(messageOf(results[0].reason)); if (results[1].status === 'fulfilled') setConfig(results[1].value); else if (results[0].status === 'fulfilled' && !results[0].value.creator) setError('Creator terms could not be loaded. Please try again before creating your profile.'); setLoading(false); }, [isAuthenticated]);
  useEffect(() => { void load(); }, [load]);
  const refresh = useCallback(async () => { await load(true); }, [load]);
  const archive = async (listing: CreatorListing) => { setActionBusy(listing.id); setMessage(''); try { await MarketplaceService.request(`/me/listings/${encodeURIComponent(listing.id)}/archive`, { method: 'POST', body: JSON.stringify({}) }); setMessage('Product archived. Existing paid purchases remain accessible.'); await refresh(); } catch (err) { setMessage(messageOf(err)); } finally { setActionBusy(''); } };
  const creator = workspace?.creator; const summary = workspace?.summary || {}; const products = workspace?.products || []; const orders = workspace?.orders || [];
  const tabs = [{ id: 'overview', name: 'Overview', icon: LayoutDashboard }, { id: 'products', name: 'Products', icon: Package }, { id: 'memberships', name: 'Memberships', icon: Users }, { id: 'earnings', name: 'Orders & earnings', icon: Wallet }, { id: 'profile', name: 'Your storefront', icon: Store }, { id: 'payouts', name: 'Payout setup', icon: Banknote }, { id: 'plan', name: 'Your plan', icon: CreditCard }];
  return <main className="market-page"><div className="studio-container">{!isAuthenticated ? <CreatorWelcome/> : loading ? <MarketLoading label="Opening your creator space…"/> : error ? <MarketError message={error} onRetry={() => void load()}/> : !creator ? <><MarketPageHeading kicker="Every good idea starts somewhere" title="Let’s make a little" emphasis="space for yours." description="Set up your creator profile. Then add your first original product, complete payout checks, and get ready to share your work."/><ProfileForm config={config} onboard onSaved={refresh}/></> : <>
  <header className="market-page-heading"><div><div className="market-kicker-row"><p className="eyebrow">YOUR CREATOR SPACE</p><StatusPill value={creator.status}/></div><h1 style={{ fontSize: 'clamp(31px,4vw,47px)' }}>{creator.displayName}<em style={{ fontFamily: 'Georgia,serif', fontWeight: 400 }}>, let’s make things.</em></h1><p>Little details, big possibilities. Everything you need to share your work.</p></div><button className="btn btn-secondary" onClick={() => navigate(getCreatorPath(creator.slug))} disabled={creator.status !== 'approved'}>View storefront<ArrowUpRight size={16}/></button></header>
  {!!creator.reviewReason && <Notice tone={creator.status === 'rejected' || creator.status === 'suspended' ? 'error' : 'info'}>{String(creator.reviewReason)}</Notice>}{creator.status !== 'approved' && <div className="market-inline-notice">{creator.status === 'pending' ? 'Your profile is in review. You can prepare drafts and submit payout details while you wait. Your storefront opens after approval.' : 'Your storefront is currently unavailable. Review the feedback above, update your profile, or contact support.'}</div>}
  <CreatorAgreementUpdate creator={creator} config={config} onSaved={refresh}/>
  <nav className="market-tabs" role="tablist" aria-label="Creator workspace">{tabs.map(({ id, name, icon: Icon }) => <button id={`creator-tab-${id}`} key={id} role="tab" aria-selected={tab === id} aria-controls="creator-tab-panel" tabIndex={tab === id ? 0 : -1} onClick={() => setTab(id)} onKeyDown={event => { const index = tabs.findIndex(t => t.id === tab); const nextIndex = event.key === 'ArrowRight' ? (index + 1) % tabs.length : event.key === 'ArrowLeft' ? (index + tabs.length - 1) % tabs.length : event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : -1; if (nextIndex >= 0) { event.preventDefault(); setTab(tabs[nextIndex].id); document.getElementById(`creator-tab-${tabs[nextIndex].id}`)?.focus(); } }}><Icon size={14}/>{name}</button>)}</nav>
  <div id="creator-tab-panel" role="tabpanel" aria-labelledby={`creator-tab-${tab}`}>
  {tab === 'overview' && <><div className="market-stats"><div className="market-stat"><p>Products created this period</p><strong>{summary.createdThisPeriod ?? 0}</strong><small>{summary.unlimited ? 'Unlimited creations in your paid period' : typeof summary.productLimit === 'number' ? `${summary.remainingCreatesThisPeriod ?? 0} of ${summary.productLimit} monthly creations remaining` : 'Choose a paid creator plan'}</small></div><div className="market-stat"><p>Verified paid orders</p><strong>{summary.paidOrders ?? 0}</strong><small>Completed, verified customer payments</small></div><div className="market-stat"><p>Your proceeds</p><strong>{marketplaceMoney((summary.sellerPaise || 0) / 100)}</strong><small>After recorded platform commission</small></div><div className="market-stat"><p>Recorded payable balance</p><strong>{marketplaceMoney((summary.payablePaise || 0) / 100)}</strong><small>Subject to provider settlement and adjustments</small></div></div><div className="market-overview-grid"><section className="market-panel"><h2>Good things take a few small steps.</h2><div className="market-steps">{[{ title: 'Introduce yourself', text: creator.status === 'approved' ? 'Your creator profile is approved.' : 'Your profile is awaiting review.', done: creator.status === 'approved', action: 'profile' }, { title: 'Add your first product', text: products.length ? `${products.length} ${products.length === 1 ? 'product' : 'products'} in your workspace. Keep making.` : 'Save a draft, upload its private ZIP, and submit it for review.', done: products.some(p => p.status === 'active'), action: 'products' }, { title: 'Get payouts ready', text: 'Submit private identity and bank details. Provider verification is a separate step.', done: (creator.kyc as any)?.status === 'submitted', action: 'payouts' }].map((step, i) => <div className="market-step" key={step.title}><span>{step.done ? <Check size={13}/> : i + 1}</span><div><h3>{step.title}</h3><p>{step.text}</p><button className="text-button" style={{ fontSize: 11, marginTop: 8 }} onClick={() => setTab(step.action)}>{step.done ? 'View details' : 'Continue'}<ArrowRight size={12}/></button></div></div>)}</div></section><section className="market-panel"><Sparkles size={26} strokeWidth={1.3}/><h2 style={{ marginTop: 18 }}>Make a little more possible.</h2><p>One helpful product can be a great beginning. Tell buyers who it is for, show what is inside, and make your licence clear.</p><button className="btn btn-primary" style={{ marginTop: 20 }} onClick={() => { setTab('products'); setEditing(null); }}><Plus size={15}/>Add a product</button><p className="market-note">Need more room? Explore creator plans or build a membership around your original work.</p><button className="text-button" onClick={() => navigate('/pricing')}>Explore creator plans<ArrowUpRight size={14}/></button></section></div></>}
  {tab === 'products' && <section><div className="market-section-heading"><div><h2>Your ideas, ready to share.</h2><p>Draft, refine, and send your products for review.</p></div><button className="btn btn-primary" onClick={() => { setMessage(''); setEditing(null); }}><Plus size={15}/>Add product</button></div>{message && <Notice>{message}</Notice>}{products.length ? <div className="market-listing-list">{products.map(listing => <article className="market-listing" key={listing.id}><img className="market-listing-thumb" src={listing.image} alt="" onError={event => { event.currentTarget.style.visibility = 'hidden'; }}/><div className="market-listing-main"><StatusPill value={listing.status}/><h3>{listing.title}</h3><div className="market-listing-meta"><span>{marketplaceMoney(listing.price)}</span><span>{listing.categoryLabel || listing.category}</span><span>{(listing.file as any)?.uploaded ? 'Private ZIP ready' : 'ZIP needed'}</span>{listing.membershipEligible && <span>Included in memberships</span>}</div>{!!listing.reviewReason && <p className="market-review-note">{String(listing.reviewReason)}</p>}</div><div className="market-listing-actions"><button className="btn btn-secondary" onClick={() => setEditing(listing)}><Pencil size={13}/>Edit product</button>{listing.status !== 'archived' && <AsyncButton className="btn-secondary" busy={actionBusy === listing.id} busyLabel="Archiving…" onClick={() => void archive(listing)}>Archive</AsyncButton>}</div></article>)}</div> : <MarketEmpty title="Every collection starts with one." description="Add your first digital product. A clear description, useful preview, and honest licence go a long way." action="Add your first product" onAction={() => setEditing(null)} icon={Package}/>}<p className="market-note">Edits to published products return them to draft for review. Previous paid orders retain access to the files they purchased.</p></section>}
  {tab === 'memberships' && ((workspace?.entitlement as any)?.features?.customerMemberships ? <CreatorMembershipPlans creator={creator}/> : <MarketEmpty title="Memberships are included in Studio" description="Upgrade to Studio at ₹899/month to publish memberships for your customers. Your existing members retain valid paid access." action="View creator plans" onAction={() => navigate('/pricing')} icon={Users}/>)}
  {tab === 'earnings' && <section>{Array.isArray(workspace?.analytics) && <details className="market-panel"><summary>Advanced analytics · Last 30 days</summary><p className="market-note">Gross verified payments by UTC date, before refund and provider fee adjustments.</p><div className="market-table-wrap"><table className="market-table"><thead><tr><th>Date</th><th>Verified charges</th><th>Gross sales</th></tr></thead><tbody>{(workspace.analytics as any[]).map(day => <tr key={day.day}><td>{day.day}</td><td>{day.paidOrders}</td><td>{marketplaceMoney(day.grossPaise / 100)}</td></tr>)}</tbody></table></div></details>}<div className="market-section-heading"><div><h2>Every sale, a little progress.</h2><p>Your verified payment records and recorded proceeds.</p></div><button className="btn btn-secondary" onClick={() => void refresh()}><RefreshCw size={14}/>Refresh</button></div><div className="market-stats">{[['Gross product sales', summary.grossPaise], ['Platform commission', summary.commissionPaise], ['Recorded refunds', summary.refundPaise], ['Recorded payable balance', summary.payablePaise]].map(([label, amount]) => <div className="market-stat" key={String(label)}><p>{String(label)}</p><strong>{marketplaceMoney(Number(amount || 0) / 100)}</strong></div>)}</div><div className="market-inline-notice">A recorded balance is not proof of a bank credit. Payment-provider settlement, refund and dispute adjustments determine the actual amount and timing. No settlement is marked complete without provider confirmation.</div>{orders.length ? <div className="market-table-wrap"><table className="market-table"><thead><tr><th>Order</th><th>Products</th><th>Payment</th><th>Delivery</th><th>Settlement</th></tr></thead><tbody>{orders.map(order => <tr key={order.id}><td>{order.orderNumber || String(order.id).slice(-12)}<small>{marketplaceDate(order.createdAt)}</small></td><td>{Array.isArray(order.items) ? order.items.map((item: any) => item.title || item.productTitle || 'Digital product').join(', ') : 'Digital product'}<small>{marketplaceMoney(order.marketplace?.grossPaise ? order.marketplace.grossPaise / 100 : order.total || 0)}</small></td><td><StatusPill value={order.paymentStatus || order.status || 'pending'}/></td><td><StatusPill value={order.deliveryStatus || 'pending'}/><small>Email: {String(order.emailDelivery?.status || 'not_queued').replace(/_/g, ' ')}</small><small>Download: {String(order.downloadStatus || 'not_downloaded').replace(/_/g, ' ')}</small></td><td><StatusPill value={order.settlementStatus || 'pending_provider'}/></td></tr>)}</tbody></table></div> : <MarketEmpty title="Your first sale is a beginning." description="Orders will appear here as buyers discover your products. We will show payment, delivery, and settlement status separately." icon={Wallet}/>}<MembershipEarnings earnings={workspace?.membershipEarnings}/></section>}
  {tab === 'profile' && <><div className="market-panel"><h2>Your shareable storefront</h2><p>Your permanent link opens publicly after profile approval.</p><input readOnly aria-label="Your storefront URL" value={`${window.location.origin}${getCreatorPath(creator.slug)}`} onFocus={event => event.target.select()}/></div><ProfileForm creator={creator} config={config} onSaved={refresh}/></>}
  {tab === 'payouts' && <PayoutForm creator={creator} onSaved={refresh}/>}
  {tab === 'plan' && <><div className="market-section-heading"><div><h2>A little room to grow.</h2><p>Your paid creator plans and renewal status.</p></div><button className="btn btn-secondary" onClick={() => navigate('/pricing')}>Explore plans<ArrowUpRight size={15}/></button></div><CustomerMemberships embedded audience="creator"/></>}
  </div>{editing !== undefined && <ListingEditor listing={editing} allowMembership={!!(workspace?.entitlement as any)?.features?.customerMemberships} categories={config?.categories || defaultCategories} onClose={() => setEditing(undefined)} onSaved={refresh}/>}
  </>}</div></main>;
};
export default CreatorHubPage;
